import{_ as n,a0 as g,w as p,s as i,I as r,x as s,a1 as t,A as l,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const O=JSON.parse('{"title":"CentOS上配置rsyslog客户端用以远程记录日志 | LCTT x X-CMD","titleTemplate":false,"description":"CentOS上配置rsyslog客户端用以远程记录日志 | LCTT (201502) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"CentOS上配置rsyslog客户端用以远程记录日志 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"CentOS上配置rsyslog客户端用以远程记录日志 | LCTT (201502) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201502/20141210 How to configure rsyslog client for remote logging on CentOS","title":"CentOS上配置rsyslog客户端用以远程记录日志","tag":"201502","desc":""},"relativePath":"201502/20141210 How to configure rsyslog client for remote logging on CentOS.md","filePath":"[post].md"}'),y={name:"201502/20141210 How to configure rsyslog client for remote logging on CentOS.md"};function d(u,o,m,f,C,S){const e=g("Link");return p(),i("div",null,[o[19]||(o[19]=r("h1",{id:"centos上配置rsyslog客户端用以远程记录日志",tabindex:"-1"},[s("CentOS上配置rsyslog客户端用以远程记录日志 "),r("a",{class:"header-anchor",href:"#centos上配置rsyslog客户端用以远程记录日志","aria-label":"Permalink to “CentOS上配置rsyslog客户端用以远程记录日志”"},"​")],-1)),o[20]||(o[20]=r("p",null,[r("strong",null,"rsyslog"),s("是一个开源工具，被广泛用于Linux系统以通过TCP/UDP协议转发或接收日志消息。rsyslog守护进程可以被配置成两种环境，一种是配置成日志收集服务器，rsyslog进程可以从网络中收集其它主机上的日志数据，这些主机会将日志配置为发送到另外的远程服务器。rsyslog的另外一个用法，就是可以配置为客户端，用来过滤和发送内部日志消息到本地文件夹（如/var/log）或一台可以路由到的远程rsyslog服务器上。")],-1)),r("p",null,[o[1]||(o[1]=s("假定你的网络中已经有一台",-1)),t(e,{href:"http://xmodulo.com/configure-syslog-server-linux.html"},{default:l(()=>[...o[0]||(o[0]=[s("已经配置好并启动的",-1)])]),_:1}),o[2]||(o[2]=s("rsyslog服务器，本指南将为你展示如何来设置CentOS系统将其内部日志消息路由到一台远程rsyslog服务器上。这将大大改善你的系统磁盘空间的使用，尤其是当你还没有一个用于/var目录的独立的大分区。",-1))]),o[21]||(o[21]=a(`<h3 id="步骤一-安装rsyslog守护进程" tabindex="-1">步骤一： 安装Rsyslog守护进程 <a class="header-anchor" href="#步骤一-安装rsyslog守护进程" aria-label="Permalink to “步骤一： 安装Rsyslog守护进程”">​</a></h3><p>在CentOS 6和7上，rsyslog守护进程已经预先安装了。要验证rsyslog是否已经安装到你的CentOS系统上，请执行如下命令：</p><pre><code># rpm -qa | grep rsyslog
# rsyslogd -v 
</code></pre><p><img src="https://farm8.staticflickr.com/7502/15988316295_ac2e07e7f3_z.jpg" alt=""></p><p>如果处于某种原因，rsyslog守护进程没有出现在你的系统中，请使用以下命令来安装：</p><pre><code> # yum install rsyslog 
</code></pre><h3 id="步骤二-配置rsyslog守护进程为客户端" tabindex="-1">步骤二： 配置Rsyslog守护进程为客户端 <a class="header-anchor" href="#步骤二-配置rsyslog守护进程为客户端" aria-label="Permalink to “步骤二： 配置Rsyslog守护进程为客户端”">​</a></h3><p>接下来的步骤，是要将你的CentOS机器转变成rsyslog客户端，将其所有内部日志消息发送到远程中央日志服务器上。</p><p>要实现该功能，请使用你喜爱的文本编辑器打开位于/etc路径下的rsyslog主配置文件：</p><pre><code># nano /etc/rsyslog.conf 
</code></pre><p>开启文件用于编辑后，你需要添加以下声明到文件底部。将IP地址替换为你的远程rsyslog服务器的IP地址。</p><pre><code>*.*  @192.168.1.25:514 
</code></pre><p>上面的声明告诉rsyslog守护进程，将系统上各个设备的各种日志消息路由到远程rsyslog服务器（192.168.1.25）的UDP端口514。</p><p>如果出于某种原因，你需要更为可靠的协议，如TCP，而rsyslog服务器也被配置为监听TCP连接，你必须在远程主机的IP地址前添加一个额外的@字符，像下面这样：</p><pre><code>*.*  @@192.168.1.25:514 
</code></pre><p>注意，你也可以将rsyslog服务器的IP地址替换成它的主机名（FQDN）。</p><p>如果你只想要转发服务器上的指定设备的日志消息，比如说内核设备，那么你可以在rsyslog配置文件中使用以下声明。</p><pre><code>kern.* @192.168.1.25:514 
</code></pre><p>修改配置文件后，你需要重启进程以激活修改：</p><p><strong>CentOS 7：</strong></p><pre><code># systemctl restart rsyslog.service 
</code></pre><p><strong>CentOS 6：</strong></p><pre><code> # service rsyslog restart 
</code></pre><p>####非 syslog 日志的转发</p><p>在另外一种环境中，让我们假定你已经在机器上安装了一个名为“foobar”的应用程序，它会在/var/log下生成foobar.log日志文件。现在，你想要将它的日志定向到rsyslog服务器，这可以通过像下面这样在rsyslog配置文件中加载imfile模块来实现。</p><p>首先，加载imfile模块，这只需做一次。</p><pre><code>module(load=&quot;imfile&quot; PollingInterval=&quot;5&quot;) 
</code></pre><p>然后，指定日志文件的路径以便imfile模块可以检测到：</p><pre><code>input(type=&quot;imfile&quot;
      File=&quot;/var/log/foobar.log&quot;
      Tag=&quot;foobar&quot;
      Severity=&quot;error&quot;
      Facility=&quot;local7&quot;)
</code></pre><p>最后，定向local7设备到远程rsyslog服务器：</p><pre><code>local7.* @192.168.1.25:514
</code></pre><p>别忘了重启rsyslog进程哦！</p><h3 id="步骤三-让rsyslog进程自动启动" tabindex="-1">步骤三： 让Rsyslog进程自动启动 <a class="header-anchor" href="#步骤三-让rsyslog进程自动启动" aria-label="Permalink to “步骤三： 让Rsyslog进程自动启动”">​</a></h3><p>要让rsyslog客户端在每次系统重启后自动启动，请运行以下命令：</p><p><strong>CentOS 7：</strong></p><pre><code># systemctl enable rsyslog.service 
</code></pre><p><strong>CentOS 6：</strong></p><pre><code># chkconfig rsyslog on 
</code></pre><h3 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to “小结”">​</a></h3>`,39)),r("p",null,[o[4]||(o[4]=s("在本教程中，我演示了如何将CentOS系统转变成rsyslog客户端以强制它发送日志消息到远程rsyslog服务器。这里我假定rsyslog客户端和服务器之间的连接是安全的（如，在有防火墙保护的公司网络中）。不管在任何情况下，都不要配置rsyslog客户端将日志消息通过不安全的网络转发，或者，特别是通过互联网转发，因为syslog协议是一个明文协议。要进行安全传输，可以考虑使用",-1)),t(e,{href:"http://www.rsyslog.com/doc/rsyslog_tls.html"},{default:l(()=>[...o[3]||(o[3]=[s("TLS/SSL",-1)])]),_:1}),o[5]||(o[5]=s("来加密日志消息的传输。",-1))]),o[22]||(o[22]=r("hr",null,null,-1)),r("p",null,[o[7]||(o[7]=s("via: ",-1)),t(e,{href:"http://xmodulo.com/configure-rsyslog-client-centos.html"},{default:l(()=>[...o[6]||(o[6]=[s("http://xmodulo.com/configure-rsyslog-client-centos.html",-1)])]),_:1})]),r("p",null,[o[11]||(o[11]=s("作者：",-1)),t(e,{href:"http://xmodulo.com/author/caezsar"},{default:l(()=>[...o[8]||(o[8]=[s("Caezsar M",-1)])]),_:1}),o[12]||(o[12]=s(" 译者：",-1)),t(e,{href:"https://github.com/GOLinux"},{default:l(()=>[...o[9]||(o[9]=[s("GOLinux",-1)])]),_:1}),o[13]||(o[13]=s(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:l(()=>[...o[10]||(o[10]=[s("wxy",-1)])]),_:1})]),r("p",null,[o[16]||(o[16]=s("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...o[14]||(o[14]=[s("LCTT",-1)])]),_:1}),o[17]||(o[17]=s(" 原创翻译，",-1)),t(e,{href:"http://linux.cn/"},{default:l(()=>[...o[15]||(o[15]=[s("Linux中国",-1)])]),_:1}),o[18]||(o[18]=s(" 荣誉推出",-1))])])}const P=n(y,[["render",d]]);export{O as __pageData,P as default};
